import fs from 'node:fs';
import path from 'node:path';

const DB_PATH = '/home/user/project/data/kanban.sqlite';

let dbInstance: Database.Database | null = null;

export function getDb() {
  if (dbInstance) {
    return dbInstance;
  }

  const dir = path.dirname(DB_PATH);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const db = new Database(DB_PATH);
  db.pragma('journal_mode = WAL');

  // Create table if not exists
  db.exec(`
    CREATE TABLE IF NOT EXISTS cards (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      column_id TEXT NOT NULL,
      position INTEGER NOT NULL
    );
  `);

  // Check if empty and seed if needed
  const count = db.prepare('SELECT COUNT(*) as count FROM cards').get() as { count: number };
  if (count.count === 0) {
    const insert = db.prepare('INSERT INTO cards (title, column_id, position) VALUES (?, ?, ?)');

    const seedData = [
      { column_id: 'todo', title: 'Write project spec', position: 0 },
      { column_id: 'todo', title: 'Design database schema', position: 1 },
      { column_id: 'todo', title: 'Set up CI pipeline', position: 2 },
      { column_id: 'in-progress', title: 'Implement board UI', position: 0 },
      { column_id: 'in-progress', title: 'Wire up server functions', position: 1 },
      { column_id: 'done', title: 'Kickoff meeting', position: 0 },
    ];

    const transaction = db.transaction(() => {
      for (const card of seedData) {
        insert.run(card.title, card.column_id, card.position);
      }
    });
    transaction();
  }

  dbInstance = db;
  return db;
}

import { createServerFn } from '@tanstack/react-start';
import { getDb } from './db';
import { z } from 'zod';

export const getCardsFn = createServerFn({ method: 'GET' })
  .handler(async () => {
    const db = getDb();
    const rows = db.prepare('SELECT id, title, column_id, position FROM cards ORDER BY column_id, position ASC').all() as Array<{
      id: number;
      title: string;
      column_id: string;
      position: number;
    }>;
    return rows;
  });

const moveCardSchema = z.object({
  cardId: z.number(),
  destColumnId: z.string(),
  destPosition: z.number(),
});

export const moveCardFn = createServerFn({ method: 'POST' })
  .validator((data: unknown) => moveCardSchema.parse(data))
  .handler(async ({ data }) => {
    const { cardId, destColumnId, destPosition } = data;
    const db = getDb();

    // Perform inside transaction to ensure atomicity and consistency
    const transaction = db.transaction(() => {
      // Fetch all cards
      const rows = db.prepare('SELECT id, title, column_id, position FROM cards ORDER BY column_id, position ASC').all() as Array<{
        id: number;
        title: string;
        column_id: string;
        position: number;
      }>;

      // Group cards by column
      const columns: Record<string, Array<typeof rows[0]>> = {
        'todo': [],
        'in-progress': [],
        'done': []
      };

      for (const row of rows) {
        if (columns[row.column_id]) {
          columns[row.column_id].push(row);
        } else {
          columns[row.column_id] = [row];
        }
      }

      // Sort columns just to be absolutely sure they are ordered by position
      for (const colId of Object.keys(columns)) {
        columns[colId].sort((a, b) => a.position - b.position);
      }

      // Find the card to move
      let cardToMove: typeof rows[0] | undefined;
      let srcColumnId = '';
      let srcIndex = -1;

      for (const colId of Object.keys(columns)) {
        const idx = columns[colId].findIndex(c => c.id === cardId);
        if (idx !== -1) {
          cardToMove = columns[colId][idx];
          srcColumnId = colId;
          srcIndex = idx;
          break;
        }
      }

      if (!cardToMove) {
        throw new Error(`Card with ID ${cardId} not found`);
      }

      // Remove card from source column
      columns[srcColumnId].splice(srcIndex, 1);

      // Insert card into destination column
      const destCol = columns[destColumnId] || [];
      const targetPos = Math.max(0, Math.min(destPosition, destCol.length));

      // Update card's column_id
      cardToMove.column_id = destColumnId;
      destCol.splice(targetPos, 0, cardToMove);

      // Re-map positions for all cards in all columns to ensure strict 0-based contiguous integers
      const updateStmt = db.prepare('UPDATE cards SET column_id = ?, position = ? WHERE id = ?');

      for (const colId of Object.keys(columns)) {
        columns[colId].forEach((card, index) => {
          card.position = index;
          updateStmt.run(colId, index, card.id);
        });
      }
    });

    transaction();
    return { success: true };
  });

