export const APIRoute = createAPIFileRoute('/api/board')({
  GET: async ({ request }) => {
    const db = getDb();
    const rows = db.prepare('SELECT id, title, column_id, position FROM cards ORDER BY column_id, position ASC').all() as Array<{
      id: number;
      title: string;
      column_id: string;
      position: number;
    }>;

    // Group by column
    const todoCards: Array<{ id: number; title: string; position: number }> = [];
    const inProgressCards: Array<{ id: number; title: string; position: number }> = [];
    const doneCards: Array<{ id: number; title: string; position: number }> = [];

    for (const row of rows) {
      const card = { id: row.id, title: row.title, position: row.position };
      if (row.column_id === 'todo') {
        todoCards.push(card);
      } else if (row.column_id === 'in-progress') {
        inProgressCards.push(card);
      } else if (row.column_id === 'done') {
        doneCards.push(card);
      }
    }

    // Sort by position ascending just in case
    todoCards.sort((a, b) => a.position - b.position);
    inProgressCards.sort((a, b) => a.position - b.position);
    doneCards.sort((a, b) => a.position - b.position);

    // Ensure positions are contiguous starting at 0
    const formatCards = (cards: typeof todoCards) => {
      return cards.map((c, index) => ({
        id: c.id,
        title: c.title,
        position: index
      }));
    };

    const payload = {
      columns: [
        {
          id: 'todo',
          title: 'Todo',
          cards: formatCards(todoCards),
