import { createFileRoute } from '@tanstack/react-router';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getCardsFn, moveCardFn } from '../utils/cards';
import {
  DndContext,
  useSensor,
  useSensors,
  PointerSensor,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { useDroppable } from '@dnd-kit/core';
import { CSS } from '@dnd-kit/utilities';
import * as React from 'react';

export const Route = createFileRoute('/')({
  component: KanbanBoard,
});

interface Card {
  id: number;
  title: string;
  column_id: string;
  position: number;
}

interface Column {
  id: string;
  title: string;
  cards: Card[];
}

function useMounted() {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => {
    setMounted(true);
  }, []);
  return mounted;
}

function SortableCard({ card }: { card: Card }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: card.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    cursor: isDragging ? 'grabbing' : 'grab',
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="card"
    >
      {card.title}
    </div>
  );
}

function ColumnComponent({
  column,
  mounted,
}: {
  column: Column;
  mounted: boolean;
}) {
  const { setNodeRef } = useDroppable({ id: column.id });

  const cardElements = column.cards.map((card) => {
    if (mounted) {
      return <SortableCard key={card.id} card={card} />;
    }
    return (
      <div key={card.id} className="card">
        {card.title}
      </div>
    );
  });

  return (
    <div ref={mounted ? setNodeRef : undefined} className="column">
      <div className="column-header">
        <h2 className="column-title">{column.title}</h2>
        <span className="card-count">{column.cards.length}</span>
      </div>
      <div className="card-list">
        {mounted ? (
          <SortableContext
            items={column.cards.map((c) => c.id)}
            strategy={verticalListSortingStrategy}
          >
            {cardElements}
          </SortableContext>
        ) : (
          cardElements
        )}
      </div>
    </div>
  );
}

function KanbanBoard() {
  const mounted = useMounted();
  const queryClient = useQueryClient();

  const { data: cards = [], isLoading } = useQuery<Card[]>({
    queryKey: ['cards'],
    queryFn: () => getCardsFn(),
  });

  const { mutate, isPending } = useMutation({
    mutationFn: moveCardFn,
    onMutate: async (variables) => {
      await queryClient.cancelQueries({ queryKey: ['cards'] });

      const previousCards = queryClient.getQueryData<Card[]>(['cards']);

      if (previousCards) {
        const { cardId, destColumnId, destPosition } = variables;
        const nextCards = previousCards.map((c) => ({ ...c }));

        const cardIdx = nextCards.findIndex((c) => c.id === cardId);
        if (cardIdx !== -1) {
          const [movedCard] = nextCards.splice(cardIdx, 1);
          movedCard.column_id = destColumnId;

          // Get other cards in destination column
          const destCards = nextCards
            .filter((c) => c.column_id === destColumnId)
            .sort((a, b) => a.position - b.position);

          // Insert at destPosition
          destCards.splice(destPosition, 0, movedCard);

          // Re-assign positions for dest column
          destCards.forEach((c, idx) => {
            c.position = idx;
          });

          // Re-assign positions for src column if different
          const srcColumnId = previousCards[cardIdx].column_id;
          if (srcColumnId !== destColumnId) {
            const srcCards = nextCards
              .filter((c) => c.column_id === srcColumnId)
              .sort((a, b) => a.position - b.position);
            srcCards.forEach((c, idx) => {
              c.position = idx;
            });
          }

          queryClient.setQueryData(['cards'], nextCards);
        }
      }

      return { previousCards };
    },
    onError: (err, variables, context) => {
      if (context?.previousCards) {
        queryClient.setQueryData(['cards'], context.previousCards);
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['cards'] });
    },
  });

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5,
      },
    })
  );

  // Group cards into columns
  const columns: Column[] = React.useMemo(() => {
    return [
      {
        id: 'todo',
        title: 'Todo',
        cards: cards
          .filter((c) => c.column_id === 'todo')
          .sort((a, b) => a.position - b.position),
      },
      {
        id: 'in-progress',
        title: 'In Progress',
        cards: cards
          .filter((c) => c.column_id === 'in-progress')
          .sort((a, b) => a.position - b.position),
      },
      {
        id: 'done',
        title: 'Done',
        cards: cards
          .filter((c) => c.column_id === 'done')
          .sort((a, b) => a.position - b.position),
      },
    ];
  }, [cards]);

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over) return;

    const activeId = active.id as number;
    const overId = over.id;

    // Find active card and its current position
    let activeCard: Card | null = null;
    let srcColumnId = '';
    let srcIndex = -1;

    for (const col of columns) {
      const idx = col.cards.findIndex((c) => c.id === activeId);
      if (idx !== -1) {
        activeCard = col.cards[idx];
        srcColumnId = col.id;
        srcIndex = idx;
        break;
      }
    }

    if (!activeCard) return;

    let destColumnId = '';
    let destIndex = -1;

    if (
      typeof overId === 'string' &&
      ['todo', 'in-progress', 'done'].includes(overId)
    ) {
      destColumnId = overId;
      destIndex = columns.find((c) => c.id === overId)?.cards.length ?? 0;
    } else {
      // Find over card column and index
      const targetCardId = overId as number;
      for (const col of columns) {
        const idx = col.cards.findIndex((c) => c.id === targetCardId);
        if (idx !== -1) {
          destColumnId = col.id;
          destIndex = idx;
          break;
        }
      }
    }

    if (!destColumnId || destIndex === -1) return;

    // If same column and position, do nothing
    if (srcColumnId === destColumnId && srcIndex === destIndex) return;

    // If same column, and we are moving down, we need to adjust insert index
    let targetPos = destIndex;
    if (srcColumnId === destColumnId && srcIndex < destIndex) {
      // Since splicing out shifts subsequent items left, we don't need to adjust
      // actually, splice(srcIndex, 1) removes the item, so inserting at destIndex
      // will place it after the target item.
    }

    mutate({
      cardId: activeId,
      destColumnId,
      destPosition: targetPos,
    });
  }

  return (
    <div className="app-container">
      <header>
        <h1>Kanban Board</h1>
        <div className={`status-indicator ${isPending ? 'syncing' : 'synced'}`}>
          {isPending ? 'Saving...' : 'Synced with server'}
        </div>
      </header>

      {isLoading && cards.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '3rem' }}>
          Loading board...
        </div>
      ) : mounted ? (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCorners}
          onDragEnd={handleDragEnd}
        >
          <div className="board">
            {columns.map((col) => (
              <ColumnComponent key={col.id} column={col} mounted={mounted} />
            ))}
          </div>
        </DndContext>
      ) : (
        <div className="board">
          {columns.map((col) => (
            <ColumnComponent key={col.id} column={col} mounted={mounted} />
          ))}
        </div>
      )}
    </div>
  );
}

